const input = $json || {};

const sampleUserContext = {
  timezone: 'Asia/Dubai',
  identity: {
    name: 'Savaş',
    language: 'Turkish'
  },
  locations: {
    home: 'Palm Jumeirah, Dubai',
    work: 'Abu Dhabi'
  },
  schedule: {
    mondayTuesday: 'Arrives Dubai around 18:30-19:00',
    wednesdayThursday: 'Often works from home',
    weekend: 'Generally flexible'
  },
  goals: {
    fitness: 'Gym, boxing, padel, tennis, swimming, walking',
    social: 'Build a quality international social circle in Dubai',
    style: 'Stay well-groomed, stylish and confident',
    dating: 'Approach women naturally and respectfully and build genuine relationships',
    personalGrowth: 'Stoicism, confidence, conversation, storytelling, leadership',
    career: 'Cyber Security Architect'
  },
  preferences: {
    venues: 'Bars, rooftops, lounges, beach clubs, social activities',
    memberships: 'Privilee, InterNations, Meetup'
  }
};

return [{
  json: {
    requestText: input.requestText || 'Bu akşam ne yapayım?',
    userContext: Object.keys(input.userContext || {}).length
      ? input.userContext
      : sampleUserContext,
    calendarEvents: Array.isArray(input.calendarEvents)
      ? input.calendarEvents
      : [],
    now: input.now || new Date().toISOString()
  }
}];

const input = $json || {};

const requestText = String(
  input.requestText ??
  input.text ??
  input.message ??
  ''
).trim();

const userContext = input.userContext ?? {};
const calendarEvents = Array.isArray(input.calendarEvents)
  ? input.calendarEvents
  : Array.isArray(input.events)
    ? input.events
    : [];

const now = input.now ? new Date(input.now) : new Date();

if (Number.isNaN(now.getTime())) {
  throw new Error('Invalid now value supplied to Context Builder.');
}

const dubaiFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dubai',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
  weekday: 'long'
});

const parts = dubaiFormatter.formatToParts(now)
  .reduce((acc, part) => {
    acc[part.type] = part.value;
    return acc;
  }, {});

const currentDate = `${parts.year}-${parts.month}-${parts.day}`;
const currentTime = `${parts.hour}:${parts.minute}`;
const weekday = parts.weekday;

const weekdayIndex = {
  Sunday: 0,
  Monday: 1,
  Tuesday: 2,
  Wednesday: 3,
  Thursday: 4,
  Friday: 5,
  Saturday: 6
}[weekday];

const isWeekend = weekdayIndex === 0 || weekdayIndex === 6;
const isWorkday = !isWeekend;
const currentHour = Number(parts.hour);

const isMorning = currentHour >= 5 && currentHour < 12;
const isAfternoon = currentHour >= 12 && currentHour < 17;
const isEvening = currentHour >= 17 && currentHour < 22;
const isNight = currentHour >= 22 || currentHour < 5;

const isMondayOrTuesday = weekdayIndex === 1 || weekdayIndex === 2;
const isWednesdayOrThursday = weekdayIndex === 3 || weekdayIndex === 4;
const isFriday = weekdayIndex === 5;

const normalizeEvent = (event) => {
  const startValue =
    event.start?.dateTime ??
    event.start?.date ??
    event.start ??
    event.start_time ??
    event.startTime ??
    null;

  const endValue =
    event.end?.dateTime ??
    event.end?.date ??
    event.end ??
    event.end_time ??
    event.endTime ??
    null;

  const start = startValue ? new Date(startValue) : null;
  const end = endValue ? new Date(endValue) : null;

  return {
    title: event.summary ?? event.title ?? event.name ?? 'Busy',
    start: start && !Number.isNaN(start.getTime()) ? start.toISOString() : startValue,
    end: end && !Number.isNaN(end.getTime()) ? end.toISOString() : endValue,
    location: event.location ?? '',
    description: event.description ?? '',
    source: event.source ?? 'google_calendar',
    raw: event
  };
};

const normalizedEvents = calendarEvents
  .map(normalizeEvent)
  .filter(event => event.start);

const startOfTodayDubai = new Date(`${currentDate}T00:00:00+04:00`);
const endOfTodayDubai = new Date(`${currentDate}T23:59:59+04:00`);

const tomorrowDate = new Date(startOfTodayDubai.getTime() + 24 * 60 * 60 * 1000);
const endOfTomorrow = new Date(tomorrowDate.getTime() + 24 * 60 * 60 * 1000 - 1);

const startOfWeek = new Date(startOfTodayDubai);
const daysSinceMonday = (weekdayIndex + 6) % 7;
startOfWeek.setDate(startOfWeek.getDate() - daysSinceMonday);

const endOfWeek = new Date(startOfWeek.getTime() + 7 * 24 * 60 * 60 * 1000 - 1);

const parseTime = value => {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const overlaps = (event, rangeStart, rangeEnd) => {
  const start = parseTime(event.start);
  const end = parseTime(event.end) ?? start;
  if (!start) return false;
  return start <= rangeEnd && end >= rangeStart;
};

const todayEvents = normalizedEvents.filter(event =>
  overlaps(event, startOfTodayDubai, endOfTodayDubai)
);

const tomorrowEvents = normalizedEvents.filter(event =>
  overlaps(event, tomorrowDate, endOfTomorrow)
);

const weekEvents = normalizedEvents.filter(event =>
  overlaps(event, startOfWeek, endOfWeek)
);

const eventText = event =>
  `${event.title} ${event.description} ${event.location}`.toLocaleLowerCase('tr-TR');

const countMatches = patterns =>
  weekEvents.filter(event =>
    patterns.some(pattern => eventText(event).includes(pattern))
  ).length;

const fitnessCount = countMatches([
  'gym', 'boxing', 'boks', 'fitness', 'padel', 'tennis',
  'swim', 'yuzme', 'walk', 'yuruyus', 'workout'
]);

const socialCount = countMatches([
  'networking', 'internations', 'meetup', 'social', 'mixer',
  'jazz', 'stand-up', 'stand up', 'dinner', 'bar', 'party'
]);

const learningCount = countMatches([
  'learning', 'course', 'training', 'workshop', 'ai',
  'cyber', 'security', 'conference', 'toastmasters'
]);

const financeCount = countMatches([
  'finance', 'budget', 'investment', 'yatirim', 'review'
]);

const getBusyWindows = events =>
  events.map(event => ({
    title: event.title,
    start: event.start,
    end: event.end,
    location: event.location
  }));

const todayBusyWindows = getBusyWindows(todayEvents);

const defaultEveningStart =
  isMondayOrTuesday ? '19:30' :
  isWednesdayOrThursday ? '18:30' :
  isFriday || isWeekend ? '17:00' :
  '18:30';

const preferredPlanningWindow = {
  start: defaultEveningStart,
  end: '23:00',
  reason: isMondayOrTuesday
    ? 'Allow Abu Dhabi to Dubai commute and preparation time.'
    : isWednesdayOrThursday
      ? 'Often works from home, so earlier evening activities are realistic.'
      : 'Flexible day with room for social, fitness, or lifestyle activities.'
};

const commuteConstraint = {
  active: isMondayOrTuesday,
  homeArrivalEstimate: isMondayOrTuesday ? '18:30-19:00' : null,
  earliestSafeDubaiEventTime: isMondayOrTuesday ? '19:30' : null
};

const identity = userContext.identity ?? {};
const locations = userContext.locations ?? {};
const goals = userContext.goals ?? {};
const preferences = userContext.preferences ?? {};
const schedule = userContext.schedule ?? {};

const derivedContext = {
  isWeekend,
  isWorkday,
  isMorning,
  isAfternoon,
  isEvening,
  isNight,
  isMondayOrTuesday,
  isWednesdayOrThursday,
  isFriday,
  commuteConstraint,
  preferredPlanningWindow,
  fitnessActivitiesThisWeek: fitnessCount,
  socialActivitiesThisWeek: socialCount,
  learningActivitiesThisWeek: learningCount,
  financeReviewsThisWeek: financeCount,
  needsMoreFitness: fitnessCount < 3,
  needsMoreSocial: socialCount < 2,
  needsFinanceReview: financeCount < 1,
  todayEventCount: todayEvents.length,
  tomorrowEventCount: tomorrowEvents.length,
  weekEventCount: weekEvents.length,
  calendarLoad:
    weekEvents.length >= 12 ? 'high' :
    weekEvents.length >= 7 ? 'medium' :
    'low'
};

const recommendationHints = [];

if (derivedContext.needsMoreFitness) {
  recommendationHints.push('Prioritize a fitness activity if calendar and energy allow.');
}

if (derivedContext.needsMoreSocial) {
  recommendationHints.push('Consider a high-quality social or networking opportunity.');
}

if (derivedContext.needsFinanceReview) {
  recommendationHints.push('Reserve a short finance review block this week.');
}

if (commuteConstraint.active) {
  recommendationHints.push('Do not recommend early-evening Dubai events before 19:30.');
}

if (derivedContext.calendarLoad === 'high') {
  recommendationHints.push('Protect recovery time and avoid overloading the week.');
}

const context = {
  generatedAt: now.toISOString(),
  timezone: userContext.timezone ?? 'Asia/Dubai',
  request: {
    text: requestText
  },
  temporalContext: {
    currentDate,
    currentTime,
    weekday,
    weekdayIndex
  },
  userContext: {
    identity,
    locations,
    schedule,
    goals,
    preferences,
    raw: userContext.rawProfile ?? userContext
  },
  calendarContext: {
    today: todayBusyWindows,
    tomorrow: getBusyWindows(tomorrowEvents),
    thisWeek: getBusyWindows(weekEvents)
  },
  derivedContext,
  recommendationHints
};

const promptContext = [
  `Current Dubai date: ${currentDate}`,
  `Current Dubai time: ${currentTime}`,
  `Weekday: ${weekday}`,
  `User: ${identity.name ?? 'Savaş'}`,
  `Home: ${locations.home ?? 'Palm Jumeirah, Dubai'}`,
  `Work: ${locations.work ?? 'Abu Dhabi'}`,
  `Request: ${requestText || 'No explicit request supplied'}`,
  `Calendar load: ${derivedContext.calendarLoad}`,
  `Today events: ${todayEvents.length}`,
  `Tomorrow events: ${tomorrowEvents.length}`,
  `Fitness activities this week: ${fitnessCount}`,
  `Social activities this week: ${socialCount}`,
  `Learning activities this week: ${learningCount}`,
  `Finance reviews this week: ${financeCount}`,
  `Preferred planning window: ${preferredPlanningWindow.start}-${preferredPlanningWindow.end}`,
  ...recommendationHints.map(hint => `Hint: ${hint}`)
].join('\n');

return [{
  json: {
    success: true,
    context,
    promptContext,
    summary: {
      requestText,
      weekday,
      currentTime,
      todayEventCount: todayEvents.length,
      weekEventCount: weekEvents.length,
      calendarLoad: derivedContext.calendarLoad,
      preferredPlanningWindow
    }
  }
}];
